import { useEffect, useId, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { addDays, batchWithAthlete, monthDates, occursOn, shiftMonth, slotTimes, timeMinutes, todayInZone, weekDates } from './batch-calendar';
import { branchRevenueChart } from './finance-chart';
import { MobileAccountsPanel } from './mobile-admin';
import { ApiError, createApi, type Athlete, type Batch, type Branch, type Coach, type Dashboard, type Expense, type FinanceSummary, type Invoice, type Me, type Payment, type Workspace } from '@ams/api-client';

const api = createApi(() => sessionStorage.getItem('ams.token'));
const today = () => new Date().toISOString().slice(0, 10);
const currentMonth = () => `${today().slice(0, 7)}-01`;
const money = (value: unknown) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 2 }).format(Number(value || 0));
const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
type Page = 'overview' | 'athletes' | 'batches' | 'coaches' | 'branches' | 'attendance' | 'mobile-accounts' | 'fees' | 'finance';
type IconName = Page | 'menu' | 'search' | 'logout' | 'plus' | 'close';

const paths: Record<IconName, string[]> = {
  overview: ['M3 11.5 12 4l9 7.5', 'M5 10v10h14V10', 'M9 20v-6h6v6'],
  athletes: ['M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2', 'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8'],
  batches: ['M6 2v4M18 2v4M3 10h18', 'M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2Z'],
  coaches: ['M12 3 2.2 4.45 4.91.71-3.55 3.46.84 4.89L12 14.77 7.6 17.1l.84-4.89-3.55-3.46 4.91-.71L12 3Z'],
  branches: ['M3 21h18M6 21V5l6-3 6 3v16', 'M10 21v-4h4v4'],
  attendance: ['M4 5h16v16H4z', 'M8 3v4M16 3v4m-8 8 3 3 5-6'],
  'mobile-accounts': ['M7 2h10a2 2 0 0 1 2 2v16a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2Z', 'M10 18h4'],
  fees: ['M3 6h18v12H3z', 'M3 10h18', 'M7 15h3'],
  finance: ['M4 19V9M10 19V5M16 19v-7M22 19H2'],
  menu: ['M4 7h16M4 12h16M4 17h16'], search: ['m21 21-4.35-4.35', 'M11 19a8 8 0 1 0 0-16 8 8 0 0 0 0 16Z'],
  logout: ['M10 17l5-5-5-5M15 12H3', 'M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4'], plus: ['M12 5v14M5 12h14'], close: ['M6 6l12 12M18 6 6 18'],
};

function Icon({ name, size = 20 }: { name: IconName; size?: number }) {
  return <svg aria-hidden="true" viewBox="0 0 24 24" width={size} height={size} fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">{paths[name].map((path, index) => <path key={index} d={path} />)}</svg>;
}

function Brand() {
  return <div className="brand"><span className="brand-mark" aria-hidden="true"><i /><i /></span><span><strong>Rally<span>One</span></strong><small>Academy management</small></span></div>;
}

function getError(value: unknown) {
  return { message: value instanceof Error ? value.message : 'The request could not be completed.', requestId: value instanceof ApiError ? value.requestId : undefined };
}

function ErrorPanel({ error, retry }: { error?: { message: string; requestId?: string }; retry?: () => void }) {
  if (!error) return null;
  return <div className="error-panel" role="alert"><div><strong>We could not load this section.</strong><span>{error.message}</span>{error.requestId && <small>Reference: {error.requestId}</small>}</div>{retry && <button className="secondary compact" onClick={retry}>Try again</button>}</div>;
}

function Modal({ open, title, description, onClose, children }: { open: boolean; title: string; description?: string; onClose: () => void; children: ReactNode }) {
  const ref = useRef<HTMLDialogElement>(null);
  const titleId = useId();
  const descriptionId = `${titleId}-description`;
  useEffect(() => { const dialog = ref.current; if (!dialog) return; if (open && !dialog.open) dialog.showModal(); if (!open && dialog.open) dialog.close(); }, [open]);
  return <dialog ref={ref} aria-labelledby={titleId} aria-describedby={description ? descriptionId : undefined} onCancel={event => { event.preventDefault(); onClose(); }}><section className="dialog-card"><header className="dialog-title"><div><h2 id={titleId}>{title}</h2>{description && <p id={descriptionId}>{description}</p>}</div><button className="icon-button" type="button" aria-label={`Close ${title}`} onClick={onClose}><Icon name="close" /></button></header>{open && children}</section></dialog>;
}

function ActionForm({ onSubmit, children }: { onSubmit: (event: FormEvent<HTMLFormElement>) => Promise<void>; children: ReactNode }) {
  const pending = useRef(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (pending.current) return;
    pending.current = true; setBusy(true); setError('');
    try { await onSubmit(event); }
    catch (value) { setError(value instanceof Error ? value.message : 'Could not save. Please try again.'); }
    finally { pending.current = false; setBusy(false); }
  };
  return <form className="dialog-form" onSubmit={submit} aria-busy={busy}>{error && <p className="form-error" role="alert">{error}</p>}{children}{busy && <span className="form-saving" role="status">Saving...</span>}</form>;
}

function PasswordDialog({ open, onClose }: { open: boolean; onClose: () => void }) {
  const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const [saved, setSaved] = useState(false);
  useEffect(() => { if (open) setError(''); }, [open]);
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setBusy(true); setError(''); const form = event.currentTarget; const data = new FormData(form);
    try {
      if (data.get('newPassword') !== data.get('confirmPassword')) throw new Error('Passwords do not match.');
      await api.passwordChange({ currentPassword: String(data.get('currentPassword')), newPassword: String(data.get('newPassword')) });
      form.reset(); setSaved(true); onClose();
    } catch (value) { setError(value instanceof Error ? value.message : 'Could not change password.'); }
    finally { setBusy(false); }
  };
  return <>{saved && <span className="sr-only" role="status">Password changed.</span>}<Modal open={open} title="Change password" onClose={onClose}><ActionForm onSubmit={submit}><label>Current password<input name="currentPassword" type="password" autoComplete="current-password" minLength={12} required /></label><label>New password<input name="newPassword" type="password" autoComplete="new-password" minLength={12} required /></label><label>Confirm new password<input name="confirmPassword" type="password" autoComplete="new-password" minLength={12} required /></label>{error && <p className="form-error" role="alert">{error}</p>}<div className="dialog-actions"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={busy}>{busy ? 'Saving...' : 'Change password'}</button></div></ActionForm></Modal></>;
}

function PageHeader({ eyebrow, title, description, action, onAction }: { eyebrow: string; title: string; description: string; action?: string; onAction?: () => void }) {
  return <div className="page-heading"><div><span className="eyebrow green">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{action && <button className="primary" onClick={onAction}><Icon name="plus" size={18} />{action}</button>}</div>;
}

function Empty({ children }: { children: ReactNode }) { return <p className="empty-copy">{children}</p>; }

function OperationsOverview({ data, athletes, coaches, branches, batches, showRevenue }: { data?: Dashboard; athletes: Athlete[]; coaches: Coach[]; branches: Branch[]; batches: Batch[]; showRevenue: boolean }) {
  const cards = [
    { label: 'Athletes', value: athletes.filter(item => item.active).length, tone: 'violet' },
    { label: 'Coaches', value: coaches.filter(item => item.active).length, tone: 'green' },
    { label: 'Branches', value: branches.length, tone: 'orange' },
    { label: 'Active batches', value: batches.filter(item => item.active).length, tone: 'blue' },
  ];
  return <><PageHeader eyebrow="Academy overview" title="Good to see you." description={showRevenue ? "Your current operations and collections at a glance." : "Your classes and academy activity at a glance."} /><section className="metric-grid">{cards.map(card => <article key={card.label}><span className={`metric-icon ${card.tone}`}>{card.value}</span><div><strong>{card.value}</strong><small>{card.label}</small></div></article>)}{showRevenue && <article className="revenue-card"><div><strong>{money(data?.currentMonthRevenue)}</strong><small>Revenue this month</small><span>Collections minus refunds</span></div></article>}</section><section className="content-card"><div className="section-heading"><div><h2>Current schedule</h2><p>Active batches across your academy.</p></div></div><div className="overview-batches">{batches.filter(item => item.active).slice(0, 6).map(batch => <article key={batch.id}><strong>{batch.name}</strong><span>{String(batch.startTime).slice(0, 5)} - {String(batch.endTime).slice(0, 5)}</span><small>{branches.find(item => item.id === batch.branchId)?.name || 'Unassigned branch'}</small></article>)}</div>{!batches.some(item => item.active) && <Empty>No active batches yet.</Empty>}</section></>;
}

function AthletesPage({ academyId, athletes, branches, query, refresh, canEdit }: { academyId: string; athletes: Athlete[]; branches: Branch[]; query: string; refresh: () => Promise<void>; canEdit: boolean }) {
  const [selected, setSelected] = useState<Athlete | null>(); const [error, setError] = useState<ReturnType<typeof getError>>();
  const visible = athletes.filter(item => item.name.toLowerCase().includes(query.toLowerCase()));
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const body = { name: String(data.get('name')), homeBranchId: String(data.get('branch')) || null, monthlyFee: Number(data.get('fee') || 0) }; try { selected ? await api.updateAthlete(academyId, selected.id, body) : await api.createAthlete(academyId, body); setSelected(undefined); setError(undefined); await refresh(); } catch (value) { throw value; } };
  return <><PageHeader eyebrow="Directory" title="Athletes" description="View athletes in your academy." action={canEdit ? "Add athlete" : undefined} onAction={() => setSelected(null)} /><ErrorPanel error={error} /><section className="content-card"><div className="directory-grid athlete-grid">{visible.map(athlete => <article className="directory-card" key={athlete.id}><span className="avatar">{athlete.name[0]}</span><div><strong>{athlete.name}</strong><span>{branches.find(item => item.id === athlete.homeBranchId)?.name || 'Unassigned'}</span>{canEdit && <small>{money(athlete.monthlyFee)} monthly</small>}<span className={`status-badge ${athlete.active ? 'active' : 'inactive'}`}>{athlete.active ? 'Active' : 'Inactive'}</span></div>{canEdit && <button className="secondary compact" onClick={() => setSelected(athlete)}>Edit</button>}</article>)}</div>{!visible.length && <Empty>No athletes found.</Empty>}</section><Modal open={selected !== undefined} title={selected ? 'Edit athlete' : 'Add athlete'} description={selected ? 'Update the athlete name, home branch, and monthly fee.' : 'Create the athlete and optionally assign their branch and fee.'} onClose={() => setSelected(undefined)}><ActionForm key={selected?.id || 'new'} onSubmit={submit}><label>Name<input name="name" required minLength={2} maxLength={100} defaultValue={selected?.name || ''} autoFocus /></label><label>Home branch<select name="branch" defaultValue={selected?.homeBranchId || ''}><option value="">Unassigned</option>{branches.map(branch => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select></label><label>Monthly fee<input name="fee" type="number" min="0" step="0.01" required defaultValue={selected ? Number(selected.monthlyFee) : 0} /></label><div className="dialog-actions"><button type="button" className="secondary" onClick={() => setSelected(undefined)}>Cancel</button><button className="primary">{selected ? 'Save athlete' : 'Add athlete'}</button></div></ActionForm></Modal></>;
}

function CoachesPage({ academyId, coaches, query, refresh }: { academyId: string; coaches: Coach[]; query: string; refresh: () => Promise<void> }) {
  const [selected, setSelected] = useState<Coach | null>(); const [error, setError] = useState<ReturnType<typeof getError>>();
  const visible = coaches.filter(item => `${item.name} ${item.phone} ${item.email || ''}`.toLowerCase().includes(query.toLowerCase()));
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const body = { name: String(data.get('name')), phone: String(data.get('phone')), email: String(data.get('email')) || null, notes: String(data.get('notes')) || null, active: data.get('active') === 'on' }; try { selected ? await api.updateCoach(academyId, selected.id, body) : await api.createCoach(academyId, body); setSelected(undefined); setError(undefined); await refresh(); } catch (value) { throw value; } };
  return <><PageHeader eyebrow="Team" title="Coaches" description="Maintain the coaching directory used by batches and attendance." action="Add coach" onAction={() => setSelected(null)} /><ErrorPanel error={error} /><section className="content-card"><div className="directory-grid">{visible.map(coach => <article className="directory-card" key={coach.id}><span className="avatar">{coach.name[0]}</span><div><strong>{coach.name}</strong><span>{coach.phone}</span><small>{coach.email || 'No email supplied'}</small></div><button className="secondary compact" onClick={() => setSelected(coach)}>Edit</button></article>)}</div>{!visible.length && <Empty>No coaches found.</Empty>}</section><Modal open={selected !== undefined} title={selected ? 'Edit coach' : 'Add coach'} onClose={() => setSelected(undefined)}><ActionForm onSubmit={submit}><div className="form-grid"><label>Name<input name="name" required minLength={2} defaultValue={selected?.name} autoFocus /></label><label>Phone<input name="phone" type="tel" required minLength={5} defaultValue={selected?.phone} /></label><label>Email<input name="email" type="email" defaultValue={selected?.email || ''} /></label><label>Notes<textarea name="notes" maxLength={500} defaultValue={selected?.notes || ''} /></label></div><label className="check-label"><input name="active" type="checkbox" defaultChecked={selected?.active ?? true} /> Active coach</label><div className="dialog-actions"><button type="button" className="secondary" onClick={() => setSelected(undefined)}>Cancel</button><button className="primary">Save coach</button></div></ActionForm></Modal></>;
}

function BranchesPage({ academyId, branches, query, refresh, canEdit }: { academyId: string; branches: Branch[]; query: string; refresh: () => Promise<void>; canEdit: boolean }) {
  const [branch, setBranch] = useState<Branch | null>(); const [table, setTable] = useState<{ branch: Branch; table?: Branch['tables'][number] }>(); const [error, setError] = useState<ReturnType<typeof getError>>();
  const visible = branches.filter(item => `${item.name} ${item.city}`.toLowerCase().includes(query.toLowerCase()));
  const saveBranch = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const body = { name: String(data.get('name')), city: String(data.get('city')), address: String(data.get('address')) }; try { branch ? await api.updateBranch(academyId, branch.id, body) : await api.createBranch(academyId, body); setBranch(undefined); await refresh(); } catch (value) { throw value; } };
  const saveTable = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!table) return; const name = String(new FormData(event.currentTarget).get('name')); try { table.table ? await api.updateTable(academyId, table.branch.id, table.table.id, name) : await api.createTable(academyId, table.branch.id, name); setTable(undefined); await refresh(); } catch (value) { throw value; } };
  return <><PageHeader eyebrow="Locations" title="Branches & tables" description="View academy locations and tables." action={canEdit ? "Add branch" : undefined} onAction={() => setBranch(null)} /><ErrorPanel error={error} /><section className="branch-grid">{visible.map(item => <article className="content-card branch-card" key={item.id}><div className="section-heading"><div><h2>{item.name}</h2><p>{item.address}, {item.city}</p></div>{canEdit && <button className="text-button" onClick={() => setBranch(item)}>Edit</button>}</div><ul>{item.tables.map(resource => <li key={resource.id}><span>{resource.name}</span>{canEdit && <span><button className="text-button" onClick={() => setTable({ branch: item, table: resource })}>Edit</button><button className="text-button danger" onClick={async () => { if (confirm(`Delete ${resource.name}?`)) { try { await api.deleteTable(academyId, item.id, resource.id); await refresh(); } catch (value) { setError(getError(value)); } } }}>Delete</button></span>}</li>)}</ul>{canEdit && <button className="secondary" onClick={() => setTable({ branch: item })}><Icon name="plus" size={17} />Add table</button>}</article>)}</section>{!visible.length && <section className="content-card"><Empty>No branches found.</Empty></section>}<Modal open={branch !== undefined} title={branch ? 'Edit branch' : 'Add branch'} onClose={() => setBranch(undefined)}><ActionForm onSubmit={saveBranch}><label>Name<input name="name" required defaultValue={branch?.name} autoFocus /></label><div className="form-grid"><label>City<input name="city" required defaultValue={branch?.city} /></label><label>Address<input name="address" required defaultValue={branch?.address} /></label></div><div className="dialog-actions"><button type="button" className="secondary" onClick={() => setBranch(undefined)}>Cancel</button><button className="primary">Save branch</button></div></ActionForm></Modal><Modal open={Boolean(table)} title={table?.table ? 'Edit table' : 'Add table'} description={table ? `Branch: ${table.branch.name}` : undefined} onClose={() => setTable(undefined)}><ActionForm onSubmit={saveTable}><label>Name<input name="name" required defaultValue={table?.table?.name} autoFocus /></label><div className="dialog-actions"><button type="button" className="secondary" onClick={() => setTable(undefined)}>Cancel</button><button className="primary">Save table</button></div></ActionForm></Modal></>;
}

function BatchForm({ batch, draft, branches, coaches, athletes, onCancel, onSave }: { batch?: Batch | null; draft?: { date: string; startTime: string; endTime: string }; branches: Branch[]; coaches: Coach[]; athletes: Athlete[]; onCancel: () => void; onSave: (body: Parameters<typeof api.createBatch>[1]) => Promise<void> }) {
  const [branchId, setBranchId] = useState(batch?.branchId || branches[0]?.id || ''); const selectedBranch = branches.find(item => item.id === branchId); const [tableId, setTableId] = useState(batch?.tableId || selectedBranch?.tables[0]?.id || ''); const [recurrence, setRecurrence] = useState(batch?.recurrence || (draft ? 'ONCE' : 'WEEKLY'));
  useEffect(() => { if (!selectedBranch?.tables.some(item => item.id === tableId)) setTableId(selectedBranch?.tables[0]?.id || ''); }, [branchId, selectedBranch, tableId]);
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); await onSave({ name: String(data.get('name')), branchId, tableId, recurrence, oneOffDate: recurrence === 'ONCE' ? String(data.get('oneOffDate')) : null, weekdays: recurrence === 'WEEKLY' ? data.getAll('weekdays').map(Number) : [], startsOn: String(data.get('startsOn')), endsOn: String(data.get('endsOn')) || null, startTime: String(data.get('startTime')), endTime: String(data.get('endTime')), coachIds: data.getAll('coachIds').map(String), athleteIds: data.getAll('athleteIds').map(String), active: data.get('active') === 'on' }); };
  return <ActionForm onSubmit={submit}><div className="form-grid"><label>Batch name<input name="name" required defaultValue={batch?.name} autoFocus /></label><label>Schedule<select value={recurrence} onChange={event => setRecurrence(event.target.value as Batch['recurrence'])}><option value="WEEKLY">Weekly</option><option value="ONCE">One-off</option></select></label><label>Branch<select value={branchId} onChange={event => setBranchId(event.target.value)} required><option value="" disabled>Select a branch</option>{branches.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Table<select value={tableId} onChange={event => setTableId(event.target.value)} required disabled={!selectedBranch?.tables.length}><option value="" disabled>{selectedBranch?.tables.length ? 'Select a table' : 'Add a table first'}</option>{selectedBranch?.tables.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label></div>{recurrence === 'WEEKLY' ? <fieldset><legend>Weekdays</legend><div className="check-grid">{days.map((day, index) => <label className="check-label" key={day}><input type="checkbox" name="weekdays" value={index} defaultChecked={batch?.weekdays.includes(index)} />{day.slice(0, 3)}</label>)}</div></fieldset> : <label>One-off date<input name="oneOffDate" type="date" required defaultValue={batch?.oneOffDate || draft?.date || today()} /></label>}<div className="form-grid"><label>Starts on<input name="startsOn" type="date" required defaultValue={batch?.startsOn || draft?.date || today()} /></label><label>Recurrence ends<input name="endsOn" type="date" defaultValue={batch?.endsOn || draft?.date || ''} /></label><label>Start time<input name="startTime" type="time" required defaultValue={batch ? String(batch.startTime).slice(0, 5) : draft?.startTime || ''} /></label><label>End time<input name="endTime" type="time" required defaultValue={batch ? String(batch.endTime).slice(0, 5) : draft?.endTime || ''} /></label></div><fieldset><legend>Coaches</legend><div className="check-grid">{coaches.filter(item => item.active).map(item => <label className="check-label" key={item.id}><input type="checkbox" name="coachIds" value={item.id} defaultChecked={batch?.coachIds.includes(item.id)} />{item.name}</label>)}</div></fieldset><fieldset><legend>Athletes</legend><div className="check-grid">{athletes.filter(item => item.active).map(item => <label className="check-label" key={item.id}><input type="checkbox" name="athleteIds" value={item.id} defaultChecked={batch?.athleteIds.includes(item.id)} />{item.name}</label>)}</div></fieldset><label className="check-label"><input name="active" type="checkbox" defaultChecked={batch?.active ?? true} /> Active batch</label><div className="dialog-actions"><button type="button" className="secondary" onClick={onCancel}>Cancel</button><button className="primary" disabled={!tableId}>Save batch</button></div></ActionForm>;
}

function BatchesPage({ academyId, timezone, branches, athletes, coaches, batches, query, refresh, canEdit }: { academyId: string; timezone: string; branches: Branch[]; athletes: Athlete[]; coaches: Coach[]; batches: Batch[]; query: string; refresh: () => Promise<void>; canEdit: boolean }) {
  const [selected, setSelected] = useState<Batch | null>();
  const [draft, setDraft] = useState<{ date: string; startTime: string; endTime: string }>();
  const [selectedSlot, setSelectedSlot] = useState<{ date: string; halfHour: number } | null>(null);
  const [preview, setPreview] = useState<{ batch: Batch; date: string; key: string; anchor: HTMLButtonElement } | null>(null);
  const [week, setWeek] = useState(() => todayInZone(timezone));
  const [pickerMonth, setPickerMonth] = useState(() => `${todayInZone(timezone).slice(0, 7)}-01`);
  const [pickerOpen, setPickerOpen] = useState(false);
  const [selectedAthleteId, setSelectedAthleteId] = useState<string | null>(null);
  const [dropKey, setDropKey] = useState<string | null>(null);
  const [assigning, setAssigning] = useState(false);
  const [assignmentStatus, setAssignmentStatus] = useState('');
  const popoverRef = useRef<HTMLDivElement>(null);
  const pickerRef = useRef<HTMLDivElement>(null);
  const calendarScrollRef = useRef<HTMLDivElement>(null);
  const initialScroll = useRef(false);
  const [error, setError] = useState<ReturnType<typeof getError>>();
  const visible = batches.filter(item => item.name.toLowerCase().includes(query.toLowerCase()));
  const selectedAthlete = athletes.find(item => item.id === selectedAthleteId);
  const dates = weekDates(week);
  const datedBatches = dates.map(date => visible.filter(batch => occursOn(batch, date)));
  const scheduled = datedBatches.flat();
  const hours = Array.from({ length: 24 }, (_, index) => index);
  const calendarHeight = hours.length * 64;
  const dateLabel = (date: string) => new Intl.DateTimeFormat('en-IN', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' }).format(new Date(`${date}T00:00:00Z`));
  const pickerDates = monthDates(pickerMonth);
  const pickerYear = Number(pickerMonth.slice(0, 4));
  const monthLabel = new Intl.DateTimeFormat('en-IN', { month: 'long', year: 'numeric', timeZone: 'UTC' }).format(new Date(`${pickerMonth}T00:00:00Z`));
  const openPicker = (anchor: HTMLButtonElement) => {
    const panel = pickerRef.current;
    if (!panel) return;
    if (panel.matches(':popover-open')) { panel.hidePopover(); return; }
    setPickerMonth(`${week.slice(0, 7)}-01`);
    panel.showPopover();
    const rect = anchor.getBoundingClientRect();
    const { width, height } = panel.getBoundingClientRect();
    panel.style.left = `${Math.max(12, Math.min(rect.left, window.innerWidth - width - 12))}px`;
    panel.style.top = `${rect.bottom + height + 8 <= window.innerHeight ? rect.bottom + 8 : Math.max(12, rect.top - height - 8)}px`;
  };
  const save = async (body: Parameters<typeof api.createBatch>[1]) => { try { selected ? await api.updateBatch(academyId, selected.id, body) : await api.createBatch(academyId, body); setSelected(undefined); setDraft(undefined); setSelectedSlot(null); setError(undefined); await refresh(); } catch (value) { throw value; } };
  useEffect(() => { setSelectedSlot(null); }, [week]);
  useEffect(() => {
    if (initialScroll.current || !calendarScrollRef.current) return;
    const firstStart = scheduled.length ? Math.min(...scheduled.map(batch => timeMinutes(batch.startTime))) : 8 * 60;
    calendarScrollRef.current.scrollTop = Math.max(0, (Math.floor(firstStart / 60) - 1) * 64);
    initialScroll.current = true;
  }, [batches]);
  const assignAthlete = async (athleteId: string, batch: Batch) => {
    const athlete = athletes.find(item => item.id === athleteId && item.active);
    if (!canEdit || !athlete || assigning) return;
    if (batch.athleteIds.includes(athleteId)) { setAssignmentStatus(`${athlete.name} is already in ${batch.name}.`); setSelectedAthleteId(null); return; }
    setAssigning(true); setAssignmentStatus('');
    try {
      await api.updateBatch(academyId, batch.id, batchWithAthlete(batch, athleteId));
      setSelectedAthleteId(null); setError(undefined); setAssignmentStatus(`Added ${athlete.name} to ${batch.name}.`);
      await refresh();
    } catch (value) { setError(getError(value)); }
    finally { setAssigning(false); }
  };

  useEffect(() => {
    if (!preview || !popoverRef.current) return;
    const panel = popoverRef.current;
    if (!panel.matches(':popover-open')) panel.showPopover();
    const anchor = preview.anchor.getBoundingClientRect();
    const { width, height } = panel.getBoundingClientRect();
    panel.style.left = `${Math.max(12, Math.min(anchor.right + 10, window.innerWidth - width - 12))}px`;
    panel.style.top = `${Math.max(12, Math.min(anchor.top, window.innerHeight - height - 12))}px`;
    const close = () => panel.hidePopover();
    const frame = requestAnimationFrame(() => { window.addEventListener('resize', close); window.addEventListener('scroll', close, true); });
    return () => { cancelAnimationFrame(frame); window.removeEventListener('resize', close); window.removeEventListener('scroll', close, true); };
  }, [preview]);

  return <>
    <PageHeader eyebrow="Weekly schedule" title="Batches" description="View your recurring and one-off sessions." />
    <ErrorPanel error={error} />
    <div className={`batch-layout${canEdit ? '' : ' single'}`}>
    <section className="content-card batch-calendar-card">
      <div className="batch-calendar-toolbar">
        <button type="button" className="secondary compact" onClick={() => setWeek(todayInZone(timezone))}>Today</button>
        <button type="button" className="secondary compact" aria-label="Previous week" onClick={() => setWeek(addDays(dates[0]!, -7))}>&#8249;</button>
        <button type="button" className="secondary compact" aria-label="Next week" onClick={() => setWeek(addDays(dates[0]!, 7))}>&#8250;</button>
        <button type="button" className="batch-week-trigger" aria-label={`Choose week, ${dateLabel(dates[0]!)} to ${dateLabel(dates[6]!)}`} aria-haspopup="dialog" aria-expanded={pickerOpen} aria-controls="batch-week-picker" onClick={event => openPicker(event.currentTarget)}>{dateLabel(dates[0]!)} &ndash; {dateLabel(dates[6]!)} <span aria-hidden="true">&#8964;</span></button>
        {canEdit && <button type="button" className="primary compact batch-new-button" onClick={() => { popoverRef.current?.hidePopover(); setSelectedAthleteId(null); setDraft(selectedSlot ? { date: selectedSlot.date, ...slotTimes(selectedSlot.halfHour) } : undefined); setSelected(null); }}><Icon name="plus" size={16} />New</button>}
      </div>
      <div className="batch-calendar-scroll" ref={calendarScrollRef}><div className="batch-calendar">
        <div className="calendar-corner">Time</div>
        {dates.map((date, index) => <div className={`calendar-day-header${date === todayInZone(timezone) ? ' today' : ''}`} key={date}><strong>{Number(date.slice(8))}</strong><span>{days[(index + 6) % 7]!.slice(0, 3)}</span></div>)}
        <div className="calendar-hours" style={{ height: calendarHeight }}>{hours.map((hour, index) => <span key={hour} style={{ top: index * 64 }}>{String(hour).padStart(2, '0')}:00</span>)}</div>
        {dates.map((date, dayIndex) => <div className="calendar-day-lane" key={date} style={{ height: calendarHeight }}>
          {canEdit && Array.from({ length: 48 }, (_, halfHour) => <button type="button" className="calendar-slot" key={halfHour} style={{ top: halfHour * 32 }} aria-label={`Select ${dateLabel(date)} at ${slotTimes(halfHour).startTime}`} aria-pressed={selectedSlot?.date === date && selectedSlot.halfHour === halfHour} onClick={() => { popoverRef.current?.hidePopover(); setSelectedAthleteId(null); setSelectedSlot({ date, halfHour }); }} />)}
          {datedBatches[dayIndex]!.map(batch => {
            const key = `${date}-${batch.id}`;
            const top = timeMinutes(batch.startTime) * 64 / 60;
            const height = Math.max(28, (timeMinutes(batch.endTime) - timeMinutes(batch.startTime)) * 64 / 60);
            return <article className={`batch-calendar-entry${dropKey === key ? ' drop-target' : ''}${selectedAthleteId ? ' assignment-ready' : ''}`} key={batch.id} style={{ top, height }} onDragEnter={canEdit ? event => { if (event.dataTransfer.types.includes('application/x-ams-athlete-id')) { event.preventDefault(); setDropKey(key); } } : undefined} onDragOver={canEdit ? event => { if (event.dataTransfer.types.includes('application/x-ams-athlete-id')) { event.preventDefault(); event.dataTransfer.dropEffect = 'copy'; } } : undefined} onDragLeave={canEdit ? () => setDropKey(current => current === key ? null : current) : undefined} onDrop={canEdit ? event => { const athleteId = event.dataTransfer.getData('application/x-ams-athlete-id'); if (athleteId) { event.preventDefault(); setDropKey(null); void assignAthlete(athleteId, batch); } } : undefined}>
              <button type="button" className="batch-name" aria-label={selectedAthlete ? `Add ${selectedAthlete.name} to ${batch.name}` : `Show details for ${batch.name} on ${dateLabel(date)}`} aria-controls="batch-details-popover" aria-expanded={preview?.key === key} onClick={event => {
                if (selectedAthleteId) { void assignAthlete(selectedAthleteId, batch); return; }
                if (preview?.key === key && popoverRef.current?.matches(':popover-open')) popoverRef.current.hidePopover();
                else setPreview({ batch, date, key, anchor: event.currentTarget });
              }}>{batch.name}</button>
            </article>;
          })}
        </div>)}
      </div></div>
    </section>
    {canEdit && <section className="content-card batch-athletes" aria-busy={assigning}><div className="section-heading"><div><h2>Athletes</h2><p>Drag onto a batch, or select a name then a batch.</p></div></div><ul className="athlete-pool">{athletes.filter(item => item.active).map(athlete => <li key={athlete.id}><button type="button" draggable={!assigning} disabled={assigning} aria-pressed={selectedAthleteId === athlete.id} onClick={() => { popoverRef.current?.hidePopover(); setSelectedAthleteId(current => current === athlete.id ? null : athlete.id); setAssignmentStatus(''); }} onDragStart={event => { event.dataTransfer.setData('application/x-ams-athlete-id', athlete.id); event.dataTransfer.effectAllowed = 'copy'; popoverRef.current?.hidePopover(); setSelectedAthleteId(athlete.id); setAssignmentStatus(''); }} onDragEnd={() => { setSelectedAthleteId(null); setDropKey(null); }}>{athlete.name}</button></li>)}</ul>{assignmentStatus && <p className="batch-roster-status" role="status">{assignmentStatus}</p>}</section>}
    </div>
    <div id="batch-week-picker" className="batch-week-picker" popover="auto" ref={pickerRef} role="dialog" aria-label="Choose calendar week" onToggle={event => setPickerOpen(event.currentTarget.matches(':popover-open'))}>
      <div className="week-picker-calendar">
        <div className="week-picker-heading"><strong>{monthLabel}</strong><div><button type="button" aria-label="Previous month" onClick={() => setPickerMonth(shiftMonth(pickerMonth, -1))}>&#8249;</button><button type="button" aria-label="Next month" onClick={() => setPickerMonth(shiftMonth(pickerMonth, 1))}>&#8250;</button></div></div>
        <div className="week-picker-days">{['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((day, index) => <span key={index}>{day}</span>)}{pickerDates.map(date => <button type="button" key={date} className={`${date.slice(0, 7) !== pickerMonth.slice(0, 7) ? 'outside' : ''}${dates.includes(date) ? ' selected' : ''}${date === todayInZone(timezone) ? ' today' : ''}`} aria-label={dateLabel(date)} aria-pressed={dates.includes(date)} onClick={() => { setWeek(date); pickerRef.current?.hidePopover(); }}>{Number(date.slice(8))}</button>)}</div>
      </div>
      <div className="week-picker-months"><div className="week-picker-heading"><strong>{pickerYear}</strong><div><button type="button" aria-label="Previous year" onClick={() => setPickerMonth(shiftMonth(pickerMonth, -12))}>&#8249;</button><button type="button" aria-label="Next year" onClick={() => setPickerMonth(shiftMonth(pickerMonth, 12))}>&#8250;</button></div></div><div className="week-picker-month-grid">{Array.from({ length: 12 }, (_, index) => <button type="button" key={index} className={Number(pickerMonth.slice(5, 7)) === index + 1 ? 'active' : ''} aria-label={new Intl.DateTimeFormat('en-IN', { month: 'long' }).format(new Date(Date.UTC(pickerYear, index, 1)))} onClick={() => setPickerMonth(`${pickerYear}-${String(index + 1).padStart(2, '0')}-01`)}>{new Intl.DateTimeFormat('en-IN', { month: 'short' }).format(new Date(Date.UTC(pickerYear, index, 1)))}</button>)}</div><button type="button" className="week-picker-today" onClick={() => { setWeek(todayInZone(timezone)); pickerRef.current?.hidePopover(); }}>Today</button></div>
    </div>
    <div id="batch-details-popover" className="batch-popover" popover="auto" ref={popoverRef} role="dialog" aria-label={preview ? `Details for ${preview.batch.name}` : 'Batch details'} onToggle={event => { if (!event.currentTarget.matches(':popover-open')) setPreview(null); }}>
      {preview && <>
        <div className="batch-popover-heading"><h2>{preview.batch.name}</h2><button type="button" className="icon-button" aria-label="Close batch details" onClick={() => popoverRef.current?.hidePopover()}><Icon name="close" size={18} /></button></div>
        <p><strong>Date</strong><span>{dateLabel(preview.date)}</span></p>
        <p><strong>Time</strong><span>{String(preview.batch.startTime).slice(0, 5)} - {String(preview.batch.endTime).slice(0, 5)}</span></p>
        <p><strong>Location</strong><span>{branches.find(item => item.id === preview.batch.branchId)?.name || 'Unassigned'} / {branches.flatMap(item => item.tables).find(item => item.id === preview.batch.tableId)?.name || 'No table'}</span></p>
        <p><strong>Coach</strong><span>{preview.batch.coachIds.map(id => coaches.find(item => item.id === id)?.name).filter(Boolean).join(', ') || 'No coach'}</span></p>
        <div className="batch-popover-roster"><strong>Athletes</strong><div className="roster-tags">{preview.batch.athleteIds.map(id => <span key={id}>{athletes.find(item => item.id === id)?.name}</span>)}</div></div>
        {canEdit && <div className="card-actions"><button className="secondary compact" onClick={() => { popoverRef.current?.hidePopover(); setSelected(preview.batch); }}>Edit</button><button className="text-button danger" onClick={async () => { const batch = preview.batch; popoverRef.current?.hidePopover(); if (confirm(`Delete ${batch.name}?`)) { try { await api.deleteBatch(academyId, batch.id); await refresh(); } catch (value) { setError(getError(value)); } } }}>Delete</button></div>}
      </>}
    </div>
    <Modal open={selected !== undefined} title={selected ? 'Edit batch' : 'Add batch'} description={draft && !selected ? `${dateLabel(draft.date)} at ${draft.startTime}. Overlapping assignments will be rejected.` : 'Overlapping table, coach, or athlete assignments will be rejected.'} onClose={() => { setSelected(undefined); setDraft(undefined); }}><BatchForm key={selected?.id || (draft ? `${draft.date}-${draft.startTime}` : 'new')} batch={selected} draft={draft} branches={branches} coaches={coaches} athletes={athletes} onCancel={() => { setSelected(undefined); setDraft(undefined); }} onSave={save} /></Modal>
  </>;
}
function AttendancePage({ academyId, query, canEdit }: { academyId: string; query: string; canEdit: boolean }) {
  const [date, setDate] = useState(today()); const [entries, setEntries] = useState<Awaited<ReturnType<typeof api.dailyAttendance>>>([]); const [error, setError] = useState<ReturnType<typeof getError>>(); const [saved, setSaved] = useState(false); const [saving, setSaving] = useState(false); const pending = useRef(false);
  const load = async () => { try { setEntries(await api.dailyAttendance(academyId, date)); setError(undefined); } catch (value) { setError(getError(value)); } };
  useEffect(() => { void load(); }, [academyId, date]);
  const visible = entries.filter(item => item.name.toLowerCase().includes(query.toLowerCase()));
  const present = entries.filter(item => item.status === 'PRESENT').length; const absent = entries.filter(item => item.status === 'ABSENT').length; const excused = entries.filter(item => item.status === 'EXCUSED').length; const marked = present + absent + excused; const rate = entries.length ? Math.round(present / entries.length * 100) : 0;
  const setStatus = (id: string, status: 'PRESENT' | 'ABSENT' | 'EXCUSED') => { setSaved(false); setEntries(current => current.map(item => item.personId === id ? { ...item, status } : item)); };
  return <><PageHeader eyebrow="Daily register" title="Attendance" description={canEdit ? "Mark every active athlete and coach for the selected day." : "View attendance for athletes in your batches."} /><div className="toolbar"><label>Date<input type="date" value={date} onChange={event => setDate(event.target.value)} /></label>{canEdit && <><button className="secondary" onClick={() => { setSaved(false); setEntries(current => current.map(item => ({ ...item, status: 'PRESENT' }))); }}>Mark all present</button><button className="primary" disabled={saving} onClick={async () => { if (pending.current) return; pending.current = true; setSaving(true); try { await api.saveDailyAttendance(academyId, { localDate: date, entries: entries.filter(item => item.status).map(item => ({ personType: item.personType as 'ATHLETE' | 'COACH', personId: item.personId, status: item.status as 'PRESENT' | 'ABSENT' | 'EXCUSED' })) }); setSaved(true); setError(undefined); await load(); } catch (value) { setError(getError(value)); } finally { pending.current = false; setSaving(false); } }}>{saving ? 'Saving...' : 'Save attendance'}</button></>}</div><ErrorPanel error={error} retry={() => void load()} />{saved && <p className="success-note" role="status">Attendance saved.</p>}<section className="attendance-insights" aria-label="Attendance insights"><article className="attendance-rate"><span>Attendance rate</span><strong>{rate}%</strong><div className="rate-track" aria-hidden="true"><i style={{ width: `${rate}%` }} /></div><small>{marked} of {entries.length} marked</small></article><article><span>Present</span><strong>{present}</strong><small>Checked in today</small></article><article><span>Absent</span><strong>{absent}</strong><small>Marked absent</small></article><article><span>Excused</span><strong>{excused}</strong><small>Approved absence</small></article></section><section className="content-card"><div className="section-heading"><div><h2>Daily register</h2><p>{entries.length - marked} still need a status.</p></div></div><div className="register-list">{visible.map(item => <article key={`${item.personType}-${item.personId}`}><div><strong>{item.name}</strong><small>{item.personType.toLowerCase()}</small></div><div role="group" aria-label={`Attendance for ${item.name}`}>{(['PRESENT', 'ABSENT', 'EXCUSED'] as const).map(status => <button key={status} className={item.status === status ? 'selected' : ''} aria-pressed={item.status === status} onClick={() => setStatus(item.personId, status)} disabled={!canEdit}>{status.toLowerCase()}</button>)}</div></article>)}</div>{!visible.length && <Empty>No active people found.</Empty>}</section></>;
}

function FeesPage({ academyId, athletes, branches, refresh }: { academyId: string; athletes: Athlete[]; branches: Branch[]; refresh: () => Promise<void> }) {
  const [billingMonth, setBillingMonth] = useState(currentMonth()); const [invoices, setInvoices] = useState<Invoice[]>([]); const [error, setError] = useState<ReturnType<typeof getError>>(); const [athlete, setAthlete] = useState<Athlete>(); const [invoice, setInvoice] = useState<Invoice>(); const [payment, setPayment] = useState<Invoice>(); const [generating, setGenerating] = useState(false);
  const load = async () => { try { setInvoices(await api.invoices(academyId, billingMonth)); setError(undefined); } catch (value) { setError(getError(value)); } };
  const payableInvoice = (athleteId: string) => invoices.find(item => item.athleteId === athleteId && item.status !== 'VOID' && Number(item.balance) > 0);
  useEffect(() => { void load(); }, [academyId, billingMonth]);
  return <><PageHeader eyebrow="Monthly dues" title="Fees" description="Configure athlete fees, generate invoices, and collect balances." action="Generate invoices" onAction={() => setGenerating(true)} /><div className="toolbar"><label>Billing month<input type="month" value={billingMonth.slice(0, 7)} onChange={event => setBillingMonth(`${event.target.value}-01`)} /></label></div><ErrorPanel error={error} retry={() => void load()} /><section className="content-card"><div className="section-heading"><div><h2>Athlete fee settings</h2><p>Home branch and monthly fee determine generated invoices.</p></div></div><div className="responsive-table"><table><thead><tr><th>Athlete</th><th>Home branch</th><th>Monthly fee</th><th>Actions</th></tr></thead><tbody>{athletes.map(item => <tr key={item.id}><td data-label="Athlete">{item.name}</td><td data-label="Home branch">{branches.find(branch => branch.id === item.homeBranchId)?.name || 'Unassigned'}</td><td data-label="Monthly fee">{money(item.monthlyFee)}</td><td data-label="Actions" className="row-actions"><button className="secondary compact" onClick={() => setAthlete(item)}>Edit fee</button><button className="primary compact" disabled={!payableInvoice(item.id)} onClick={() => setPayment(payableInvoice(item.id))}>Fee paid</button></td></tr>)}</tbody></table></div></section><section className="content-card"><div className="section-heading"><div><h2>Invoices</h2><p>{billingMonth.slice(0, 7)}</p></div></div><div className="responsive-table"><table><thead><tr><th>Athlete</th><th>Amount</th><th>Paid</th><th>Balance</th><th>Status</th><th>Actions</th></tr></thead><tbody>{invoices.map(item => <tr key={item.id}><td data-label="Athlete">{item.athleteName}</td><td data-label="Amount">{money(Number(item.amount) - Number(item.discount))}</td><td data-label="Paid">{money(item.paid)}</td><td data-label="Balance">{money(item.balance)}</td><td data-label="Status"><span className={`status-badge ${item.status.toLowerCase()}`}>{item.status.replace('_', ' ')}</span></td><td data-label="Actions" className="row-actions"><button className="secondary compact" onClick={() => setInvoice(item)}>Edit</button><button className="text-button" onClick={() => window.print()}>Print</button></td></tr>)}</tbody></table></div>{!invoices.length && <Empty>No invoices for this month.</Empty>}</section><Modal open={Boolean(athlete)} title="Edit athlete fee" onClose={() => setAthlete(undefined)}>{athlete && <ActionForm onSubmit={async event => { event.preventDefault(); const data = new FormData(event.currentTarget); try { await api.updateAthlete(academyId, athlete.id, { monthlyFee: Number(data.get('fee')), homeBranchId: String(data.get('branch')) || null }); setAthlete(undefined); await refresh(); } catch (value) { throw value; } }}><label>Monthly fee<input name="fee" type="number" min="0" step="0.01" defaultValue={Number(athlete.monthlyFee)} autoFocus /></label><label>Home branch<select name="branch" defaultValue={athlete.homeBranchId || ''}><option value="">Unassigned</option>{branches.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><div className="dialog-actions"><button type="button" className="secondary" onClick={() => setAthlete(undefined)}>Cancel</button><button className="primary">Save fee</button></div></ActionForm>}</Modal><Modal open={generating} title="Generate monthly invoices" description="Existing invoices will not be duplicated." onClose={() => setGenerating(false)}><ActionForm onSubmit={async event => { event.preventDefault(); const dueDate = String(new FormData(event.currentTarget).get('dueDate')); try { setInvoices(await api.generateInvoices(academyId, { billingMonth, dueDate })); setGenerating(false); await refresh(); } catch (value) { throw value; } }}><label>Due date<input name="dueDate" type="date" required defaultValue={`${billingMonth.slice(0, 8)}10`} autoFocus /></label><div className="dialog-actions"><button type="button" className="secondary" onClick={() => setGenerating(false)}>Cancel</button><button className="primary">Generate invoices</button></div></ActionForm></Modal><Modal open={Boolean(invoice)} title="Edit invoice" onClose={() => setInvoice(undefined)}>{invoice && <ActionForm onSubmit={async event => { event.preventDefault(); const data = new FormData(event.currentTarget); try { await api.updateInvoice(academyId, invoice.id, { discount: Number(data.get('discount')), dueDate: String(data.get('dueDate')), note: String(data.get('note')) || null, status: data.get('void') === 'on' ? 'VOID' : invoice.status }); setInvoice(undefined); await load(); await refresh(); } catch (value) { throw value; } }}><label>Fixed discount<input name="discount" type="number" min="0" step="0.01" defaultValue={Number(invoice.discount)} autoFocus /></label><label>Due date<input name="dueDate" type="date" required defaultValue={invoice.dueDate} /></label><label>Note<textarea name="note" defaultValue={invoice.note || ''} /></label><label className="check-label"><input name="void" type="checkbox" disabled={invoice.status === 'VOID'} defaultChecked={invoice.status === 'VOID'} /> Void invoice</label><div className="dialog-actions"><button type="button" className="secondary" onClick={() => setInvoice(undefined)}>Cancel</button><button className="primary">Save invoice</button></div></ActionForm>}</Modal><Modal open={Boolean(payment)} title="Mark fee as paid" onClose={() => setPayment(undefined)}>{payment && <ActionForm onSubmit={async event => { event.preventDefault(); const data = new FormData(event.currentTarget); try { await api.createPayment(academyId, { invoiceId: payment.id, athleteId: payment.athleteId, branchId: payment.branchId, kind: 'FEE', amount: Number(data.get('amount')), paidOn: String(data.get('date')), method: String(data.get('method')) as Payment['method'], reference: String(data.get('reference')) || null, note: String(data.get('note')) || null }); setPayment(undefined); await load(); await refresh(); } catch (value) { throw value; } }}><div className="form-grid"><label>Amount<input name="amount" type="number" min="0.01" max={Number(payment.balance)} step="0.01" required defaultValue={Number(payment.balance)} autoFocus /></label><label>Date<input name="date" type="date" required defaultValue={today()} /></label><label>Method<select name="method" defaultValue="CASH"><option value="CASH">Cash</option><option value="UPI">UPI</option><option value="CARD">Card</option><option value="BANK_TRANSFER">Bank transfer</option><option value="OTHER">Other</option></select></label><label>Reference<input name="reference" /></label></div><label>Note<textarea name="note" /></label><div className="dialog-actions"><button type="button" className="secondary" onClick={() => setPayment(undefined)}>Cancel</button><button className="primary">Confirm fee paid</button></div></ActionForm>}</Modal></>;
}

function FinancePage({ academyId, branches, refresh }: { academyId: string; branches: Branch[]; refresh: () => Promise<void> }) {
  type Refund = Awaited<ReturnType<typeof api.refunds>>[number];
  const firstMonth = new Date(); firstMonth.setMonth(firstMonth.getMonth() - 11);
  const [start, setStart] = useState(firstMonth.toISOString().slice(0, 10)); const [end, setEnd] = useState(today()); const [summary, setSummary] = useState<FinanceSummary>(); const [payments, setPayments] = useState<Payment[]>([]); const [expenses, setExpenses] = useState<Expense[]>([]); const [refunds, setRefunds] = useState<Refund[]>([]); const [error, setError] = useState<ReturnType<typeof getError>>(); const [kind, setKind] = useState('ALL'); const [query, setQuery] = useState(''); const [incomeOpen, setIncomeOpen] = useState(false); const [expense, setExpense] = useState<Expense | null>(); const [payment, setPayment] = useState<Payment>(); const [refundPayment, setRefundPayment] = useState<Payment>();
  const [branchMonth, setBranchMonth] = useState(currentMonth().slice(0, 7)); const [monthlyBranches, setMonthlyBranches] = useState<FinanceSummary['branchDistribution']>([]); const [branchLoading, setBranchLoading] = useState(false); const [branchError, setBranchError] = useState<ReturnType<typeof getError>>(); const branchRequest = useRef(0);
  const loadBranches = async (month: string) => { const request = ++branchRequest.current; setBranchLoading(true); setMonthlyBranches([]); setBranchError(undefined); try { const value = await api.branchRevenue(academyId, `${month}-01`); if (request === branchRequest.current) setMonthlyBranches(value); } catch (value) { if (request === branchRequest.current) setBranchError(getError(value)); } finally { if (request === branchRequest.current) setBranchLoading(false); } };
  const load = async () => { void loadBranches(branchMonth); try { const [summaryValue, paymentValues, expenseValues, refundValues] = await Promise.all([api.financeSummary(academyId, start, end), api.payments(academyId), api.expenses(academyId), api.refunds(academyId)]); setSummary(summaryValue); setPayments(paymentValues); setExpenses(expenseValues); setRefunds(refundValues); setError(undefined); } catch (value) { setError(getError(value)); } };
  useEffect(() => { void load(); }, [academyId, start, end]);
  const ledger = [
    ...payments.map(item => ({ id: item.id, type: item.kind === 'FEE' ? 'PAYMENT' : 'INCOME', date: item.paidOn, detail: item.athleteName || item.note || 'Ad-hoc income', amount: Number(item.amount) - Number(item.refunded), item })),
    ...refunds.map(item => ({ id: item.id, type: 'REFUND', date: item.refundedOn, detail: item.reason, amount: -Number(item.amount), item })),
    ...expenses.map(item => ({ id: item.id, type: 'EXPENSE', date: item.incurredOn, detail: `${item.category}${item.vendor ? ` / ${item.vendor}` : ''}`, amount: -Number(item.amount), item })),
  ].filter(item => (kind === 'ALL' || item.type === kind) && item.detail.toLowerCase().includes(query.toLowerCase())).sort((a, b) => b.date.localeCompare(a.date));
  const max = Math.max(1, ...(summary?.monthlyTrend.map(item => Math.max(Number(item.revenue), Number(item.expenses))) || [1])); const pie = branchRevenueChart(monthlyBranches);
  const exportCsv = () => { const rows = [['Date', 'Type', 'Details', 'Amount'], ...ledger.map(item => [item.date, item.type, item.detail, String(item.amount)])]; const blob = new Blob([rows.map(row => row.map(cell => `"${String(cell).replaceAll('"', '""')}"`).join(',')).join('\n')], { type: 'text/csv' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `finance-${start}-${end}.csv`; link.click(); URL.revokeObjectURL(link.href); };
  return <><PageHeader eyebrow="Collections & accounting" title="Finance" description="Revenue, expenses, refunds, balances, and branch performance." action="Add income" onAction={() => setIncomeOpen(true)} /><div className="toolbar finance-toolbar"><label>From<input type="date" value={start} onChange={event => setStart(event.target.value)} /></label><label>To<input type="date" value={end} onChange={event => setEnd(event.target.value)} /></label><button className="secondary" onClick={() => setExpense(null)}><Icon name="plus" size={17} />Add expense</button><button className="secondary" onClick={exportCsv}>Export CSV</button></div><ErrorPanel error={error} retry={() => void load()} /><section className="finance-kpis"><article><span>Collections</span><strong>{money(summary?.collections)}</strong></article><article><span>Refunds</span><strong>{money(summary?.refunds)}</strong></article><article><span>Expenses</span><strong>{money(summary?.expenses)}</strong></article><article><span>Outstanding</span><strong>{money(summary?.outstanding)}</strong></article><article className="net"><span>Net result</span><strong>{money(summary?.net)}</strong></article></section><div className="finance-charts"><section className="content-card"><h2>12-month trend</h2><p className="chart-legend"><span><i />Revenue</span><span><i className="expense" />Expenses</span></p><div className="bar-chart" aria-hidden="true">{summary?.monthlyTrend.map(item => <div key={item.month}><i style={{ height: `${Number(item.revenue) / max * 100}%` }} /><b style={{ height: `${Number(item.expenses) / max * 100}%` }} /><span>{new Date(`${item.month}T00:00:00`).toLocaleDateString('en-IN', { month: 'short' })}</span></div>)}</div><table className="chart-data"><caption>Monthly revenue and expenses</caption><thead><tr><th scope="col">Month</th><th scope="col">Revenue</th><th scope="col">Expenses</th></tr></thead><tbody>{summary?.monthlyTrend.map(item => <tr key={item.month}><th>{item.month}</th><td>{money(item.revenue)}</td><td>{money(item.expenses)}</td></tr>)}</tbody></table></section><section className="content-card"><div className="section-heading finance-pie-heading"><h2>Revenue by branch</h2><label>Billing month<input type="month" value={branchMonth} onChange={event => { const month = event.target.value; if (month) { setBranchMonth(month); void loadBranches(month); } }} /></label></div><p className="finance-pie-note">Late fee payments appear in their invoice month.</p><ErrorPanel error={branchError} retry={() => void loadBranches(branchMonth)} />{branchLoading ? <p className="empty-copy" role="status">Loading branch revenue...</p> : <><div className="pie-chart" aria-hidden="true" style={{ background: pie ? `conic-gradient(${pie})` : '#e5e7eb' }} /><table className="chart-data"><caption>Branch revenue for billing month {branchMonth}</caption><thead><tr><th scope="col">Branch</th><th scope="col">Revenue</th></tr></thead><tbody>{monthlyBranches.map(item => <tr key={item.branchId || 'none'}><th>{item.branchName}</th><td>{money(item.revenue)}</td></tr>)}</tbody></table>{!monthlyBranches.length && !branchError && <Empty>No branch revenue for this month.</Empty>}</>}</section></div><section className="content-card"><div className="section-heading"><div><h2>Finance ledger</h2><p>Payments, ad-hoc income, refunds, and expenses.</p></div><div className="ledger-filters"><label>Type<select value={kind} onChange={event => setKind(event.target.value)}><option value="ALL">All entries</option><option value="PAYMENT">Fee payments</option><option value="INCOME">Ad-hoc income</option><option value="REFUND">Refunds</option><option value="EXPENSE">Expenses</option></select></label><label>Search<input type="search" value={query} onChange={event => setQuery(event.target.value)} /></label></div></div><div className="responsive-table"><table><thead><tr><th>Date</th><th>Type</th><th>Details</th><th>Amount</th><th>Actions</th></tr></thead><tbody>{ledger.map(row => <tr key={`${row.type}-${row.id}`}><td data-label="Date">{row.date}</td><td data-label="Type"><span className="status-badge">{row.type}</span></td><td data-label="Details">{row.detail}</td><td data-label="Amount">{money(row.amount)}</td><td data-label="Actions" className="row-actions">{(row.type === 'PAYMENT' || row.type === 'INCOME') && <><button className="text-button" onClick={() => setPayment(row.item as Payment)}>Edit</button><button className="text-button" disabled={Number((row.item as Payment).amount) <= Number((row.item as Payment).refunded)} onClick={() => setRefundPayment(row.item as Payment)}>Refund</button><button className="text-button danger" onClick={async () => { if (confirm('Delete this payment?')) { try { await api.deletePayment(academyId, row.id); await load(); await refresh(); } catch (value) { setError(getError(value)); } } }}>Delete</button></>}{row.type === 'EXPENSE' && <><button className="text-button" onClick={() => setExpense(row.item as Expense)}>Edit</button><button className="text-button danger" onClick={async () => { if (confirm('Delete this expense?')) { try { await api.deleteExpense(academyId, row.id); await load(); await refresh(); } catch (value) { setError(getError(value)); } } }}>Delete</button></>}</td></tr>)}</tbody></table></div>{!ledger.length && <Empty>No matching transactions.</Empty>}</section><Modal open={incomeOpen} title="Add income" onClose={() => setIncomeOpen(false)}><PaymentForm branches={branches} onCancel={() => setIncomeOpen(false)} onSave={async body => { try { await api.createPayment(academyId, body); setIncomeOpen(false); await load(); await refresh(); } catch (value) { throw value; } }} /></Modal><Modal open={Boolean(payment)} title="Edit payment" onClose={() => setPayment(undefined)}>{payment && <PaymentForm payment={payment} branches={branches} onCancel={() => setPayment(undefined)} onSave={async body => { try { await api.updatePayment(academyId, payment.id, body); setPayment(undefined); await load(); await refresh(); } catch (value) { throw value; } }} />}</Modal><Modal open={expense !== undefined} title={expense ? 'Edit expense' : 'Add expense'} onClose={() => setExpense(undefined)}><ExpenseForm expense={expense} branches={branches} onCancel={() => setExpense(undefined)} onSave={async body => { try { expense ? await api.updateExpense(academyId, expense.id, body) : await api.createExpense(academyId, body); setExpense(undefined); await load(); await refresh(); } catch (value) { throw value; } }} /></Modal><Modal open={Boolean(refundPayment)} title="Record refund" description={refundPayment ? `Available: ${money(Number(refundPayment.amount) - Number(refundPayment.refunded))}` : undefined} onClose={() => setRefundPayment(undefined)}>{refundPayment && <ActionForm onSubmit={async event => { event.preventDefault(); const data = new FormData(event.currentTarget); try { await api.createRefund(academyId, refundPayment.id, { amount: Number(data.get('amount')), refundedOn: String(data.get('date')), reason: String(data.get('reason')) }); setRefundPayment(undefined); await load(); await refresh(); } catch (value) { throw value; } }}><label>Amount<input name="amount" type="number" min="0.01" max={Number(refundPayment.amount) - Number(refundPayment.refunded)} step="0.01" required autoFocus /></label><label>Date<input name="date" type="date" required defaultValue={today()} /></label><label>Reason<textarea name="reason" required /></label><div className="dialog-actions"><button type="button" className="secondary" onClick={() => setRefundPayment(undefined)}>Cancel</button><button className="primary">Record refund</button></div></ActionForm>}</Modal></>;
}

function PaymentForm({ payment, branches, onCancel, onSave }: { payment?: Payment; branches: Branch[]; onCancel: () => void; onSave: (body: Parameters<typeof api.createPayment>[1]) => Promise<void> }) {
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); await onSave({ invoiceId: payment?.invoiceId || null, athleteId: payment?.athleteId || null, branchId: String(data.get('branch')) || null, kind: payment?.kind || 'AD_HOC', amount: Number(data.get('amount')), paidOn: String(data.get('date')), method: String(data.get('method')) as Payment['method'], reference: String(data.get('reference')) || null, note: String(data.get('note')) || null }); };
  return <ActionForm onSubmit={submit}><div className="form-grid"><label>Amount<input name="amount" type="number" min={Number(payment?.refunded || 0) || 0.01} step="0.01" required defaultValue={payment ? Number(payment.amount) : undefined} autoFocus /></label><label>Date<input name="date" type="date" required defaultValue={payment?.paidOn || today()} /></label><label>Method<select name="method" defaultValue={payment?.method || 'CASH'}><option value="CASH">Cash</option><option value="UPI">UPI</option><option value="CARD">Card</option><option value="BANK_TRANSFER">Bank transfer</option><option value="OTHER">Other</option></select></label><label>Branch<select name="branch" defaultValue={payment?.branchId || ''}><option value="">Unassigned</option>{branches.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Reference<input name="reference" defaultValue={payment?.reference || ''} /></label></div><label>Note<textarea name="note" defaultValue={payment?.note || ''} /></label><div className="dialog-actions"><button type="button" className="secondary" onClick={onCancel}>Cancel</button><button className="primary">Save payment</button></div></ActionForm>;
}

function ExpenseForm({ expense, branches, onCancel, onSave }: { expense?: Expense | null; branches: Branch[]; onCancel: () => void; onSave: (body: Parameters<typeof api.createExpense>[1]) => Promise<void> }) {
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); await onSave({ branchId: String(data.get('branch')) || null, amount: Number(data.get('amount')), incurredOn: String(data.get('date')), category: String(data.get('category')), vendor: String(data.get('vendor')) || null, note: String(data.get('note')) || null }); };
  return <ActionForm onSubmit={submit}><div className="form-grid"><label>Amount<input name="amount" type="number" min="0.01" step="0.01" required defaultValue={expense ? Number(expense.amount) : undefined} autoFocus /></label><label>Date<input name="date" type="date" required defaultValue={expense?.incurredOn || today()} /></label><label>Category<input name="category" required defaultValue={expense?.category} /></label><label>Branch<select name="branch" defaultValue={expense?.branchId || ''}><option value="">Unassigned</option>{branches.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Vendor<input name="vendor" defaultValue={expense?.vendor || ''} /></label></div><label>Note<textarea name="note" defaultValue={expense?.note || ''} /></label><div className="dialog-actions"><button type="button" className="secondary" onClick={onCancel}>Cancel</button><button className="primary">Save expense</button></div></ActionForm>;
}

const navigation: Array<{ id: Page; label: string }> = [
  { id: 'overview', label: 'Overview' }, { id: 'athletes', label: 'Athletes' }, { id: 'batches', label: 'Batches' }, { id: 'coaches', label: 'Coaches' }, { id: 'branches', label: 'Branches' }, { id: 'attendance', label: 'Attendance' }, { id: 'mobile-accounts', label: 'Mobile Accounts' }, { id: 'fees', label: 'Fees' }, { id: 'finance', label: 'Finance' },
];

export function AcademyWorkspace({ me, workspace, onSignOut }: { me: Me; workspace?: Workspace; onSignOut: () => Promise<void> }) {
  const [passwordOpen, setPasswordOpen] = useState(false); const [page, setPage] = useState<Page>(() => navigation.some(item => item.id === location.hash.slice(1)) ? location.hash.slice(1) as Page : 'overview'); const [query, setQuery] = useState(''); const [menuOpen, setMenuOpen] = useState(false); const [loading, setLoading] = useState(true); const [refreshing, setRefreshing] = useState(false); const menuRef = useRef<HTMLElement>(null); const menuButtonRef = useRef<HTMLButtonElement>(null); const [error, setError] = useState<ReturnType<typeof getError>>(); const [failedSections, setFailedSections] = useState<string[]>([]); const [dashboard, setDashboard] = useState<Dashboard>(); const [branches, setBranches] = useState<Branch[]>([]); const [athletes, setAthletes] = useState<Athlete[]>([]); const [coaches, setCoaches] = useState<Coach[]>([]); const [batches, setBatches] = useState<Batch[]>([]);
  const academyId = workspace?.academy.id || ''; const roles = workspace?.membership.roles || []; const admin = roles.includes('ADMIN'); const finance = admin || roles.includes('FINANCE'); const coach = roles.includes('COACH'); const allowed = navigation.filter(item => admin || (finance && ['overview', 'fees', 'finance'].includes(item.id)) || (coach && ['overview', 'athletes', 'batches', 'branches', 'attendance'].includes(item.id)));
  const refresh = async () => { if (!academyId) return; setRefreshing(true); const requests: Array<{ label: string; run: () => Promise<unknown>; save: (value: never) => void }> = [
    { label: 'dashboard', run: () => api.dashboard(academyId), save: value => setDashboard(value) }, { label: 'branches', run: () => api.branches(academyId), save: value => setBranches(value) }, { label: 'athletes', run: () => api.athletes(academyId), save: value => setAthletes(value) },
    ...(admin || coach ? [{ label: 'coaches', run: () => api.coaches(academyId), save: (value: never) => setCoaches(value) }, { label: 'batches', run: () => api.batches(academyId), save: (value: never) => setBatches(value) }] : []),
  ]; const results = await Promise.allSettled(requests.map(item => item.run())); const failed: string[] = []; let firstError: ReturnType<typeof getError> | undefined; results.forEach((result, index) => { const request = requests[index]; if (!request) return; if (result.status === 'fulfilled') request.save(result.value as never); else { failed.push(request.label); firstError ||= getError(result.reason); } }); setFailedSections(failed); setError(firstError); setLoading(false); setRefreshing(false); };
  useEffect(() => { void refresh(); }, [academyId]);
  useEffect(() => { const syncPage = () => { const hash = location.hash.slice(1) as Page; setPage(allowed.some(item => item.id === hash) ? hash : 'overview'); setQuery(''); }; window.addEventListener('hashchange', syncPage); return () => window.removeEventListener('hashchange', syncPage); }, [admin, finance, coach]);
  useEffect(() => { if (!allowed.some(item => item.id === page)) setPage('overview'); }, [page, admin, finance, coach]);
  useEffect(() => { window.scrollTo(0, 0); }, [page]);
  useEffect(() => { const wide = matchMedia('(min-width: 901px)'); const closeOnResize = () => { if (wide.matches) setMenuOpen(false); }; wide.addEventListener('change', closeOnResize); return () => wide.removeEventListener('change', closeOnResize); }, []);
  useEffect(() => { if (!menuOpen) return; const focusable = () => Array.from(menuRef.current?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)') || []); focusable()[0]?.focus(); const onKeyDown = (event: KeyboardEvent) => { if (event.key === 'Escape') { setMenuOpen(false); requestAnimationFrame(() => menuButtonRef.current?.focus()); } else if (event.key === 'Tab') { const items = focusable(); const first = items[0]; const last = items.at(-1); if (!first || !last) return; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } } }; document.addEventListener('keydown', onKeyDown); return () => document.removeEventListener('keydown', onKeyDown); }, [menuOpen]);
  if (!workspace) return <main className="loading"><span>No academy workspace is assigned to this account.</span><button className="secondary" onClick={() => void onSignOut()}>Sign out</button></main>;
  const navigate = (next: Page) => { setPage(next); setQuery(''); setMenuOpen(false); location.hash = next; requestAnimationFrame(() => document.querySelector<HTMLElement>('#page-content')?.focus({ preventScroll: true })); };
  const content = !allowed.some(item => item.id === page) ? null : page === 'overview' ? <OperationsOverview data={dashboard} athletes={athletes} coaches={coaches} branches={branches} batches={batches} showRevenue={finance} /> : page === 'athletes' ? <AthletesPage academyId={academyId} athletes={athletes} branches={branches} query={query} refresh={refresh} canEdit={admin} /> : page === 'batches' ? <BatchesPage academyId={academyId} timezone={workspace.academy.timezone} branches={branches} athletes={athletes} coaches={coaches} batches={batches} query={query} refresh={refresh} canEdit={admin} /> : page === 'coaches' ? <CoachesPage academyId={academyId} coaches={coaches} query={query} refresh={refresh} /> : page === 'branches' ? <BranchesPage academyId={academyId} branches={branches} query={query} refresh={refresh} canEdit={admin} /> : page === 'attendance' ? <AttendancePage academyId={academyId} query={query} canEdit={admin} /> : page === 'mobile-accounts' ? <><PageHeader eyebrow="Access" title="Mobile Accounts" description="Create and manage sign-ins for the mobile app." /><MobileAccountsPanel academyId={academyId} athletes={athletes} coaches={coaches} /></> : page === 'fees' ? <FeesPage academyId={academyId} athletes={athletes} branches={branches} refresh={refresh} /> : <FinancePage academyId={academyId} branches={branches} refresh={refresh} />;
  return <div className="app-shell">
    <aside id="academy-navigation" ref={menuRef} className={`sidebar ${menuOpen ? 'open' : ''}`} role={menuOpen ? 'dialog' : undefined} aria-modal={menuOpen ? true : undefined} aria-label={menuOpen ? 'Navigation' : undefined}><Brand /><nav aria-label="Main navigation">{allowed.map(item => <button key={item.id} className={page === item.id ? 'active' : ''} aria-current={page === item.id ? 'page' : undefined} onClick={() => navigate(item.id)}><Icon name={item.id} /><span>{item.label}</span></button>)}</nav><div className="sidebar-bottom"><button onClick={() => { setMenuOpen(false); setPasswordOpen(true); }}><span>Change password</span></button><button onClick={() => void onSignOut()}><Icon name="logout" /><span>Sign out</span></button><div className="academy-user"><span>{me.name.split(' ').map(item => item[0]).join('').slice(0, 2).toUpperCase()}</span><div><strong>{me.name}</strong><small>{roles.map(role => role.toLowerCase()).join(' / ')}</small></div></div></div></aside>
    <div className="workspace" inert={menuOpen}><header className="topbar"><button ref={menuButtonRef} className="menu-button" onClick={() => setMenuOpen(value => !value)} aria-label="Toggle navigation" aria-expanded={menuOpen} aria-controls="academy-navigation"><Icon name="menu" /></button><div className="academy-switcher"><span>{workspace.academy.name}</span><small>Academy workspace</small></div>{(['athletes', 'batches', 'coaches', 'branches', 'attendance'] as Page[]).includes(page) && <label className="search-box"><span className="sr-only">Search current page</span><Icon name="search" size={18} /><input type="search" value={query} onChange={event => setQuery(event.target.value)} placeholder="Search current page" /></label>}<span className="top-avatar" aria-hidden="true">{me.name.slice(0, 1).toUpperCase()}</span></header><main id="page-content" className={`page-content${page === 'batches' ? ' batches-page' : ''}`} tabIndex={-1}>{error && <ErrorPanel error={{ ...error, message: `Could not load ${failedSections.join(', ')}. ${error.message}` }} retry={() => void refresh()} />}{loading ? <div className="dashboard-loading" role="status" aria-label="Loading workspace"><i /><i /><i /></div> : <div key={page} className="page-view" aria-busy={refreshing}>{refreshing && <span className="sr-only" role="status">Refreshing workspace</span>}{content}</div>}</main></div>
    <PasswordDialog open={passwordOpen} onClose={() => setPasswordOpen(false)} />{menuOpen && <button className="sidebar-scrim" onClick={() => { setMenuOpen(false); requestAnimationFrame(() => menuButtonRef.current?.focus()); }} aria-label="Close navigation" />}
  </div>;
}
